/* data/cs-c/cs-12-01.js - GENERATED by tools/build.py from data/cs/cs-12-01.json. Questions are the board's; answers are our own words. Do not edit. */
(window.CS_C = window.CS_C || {})["cs-12-01"] = [{"id":"cs-12-01-01","kind":"short","q":"What is operating system ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.1"],"model":[{"t":"An operating system (OS) is system software that controls the whole computer: its hardware and its programs.","m":1},{"t":"It works as a link (interface) between the user and the hardware, so the user need not know hardware details.","m":1},{"t":"It makes the computer easy to use and uses the CPU, memory and devices efficiently. Examples: Windows, Linux.","m":1}]},{"id":"cs-12-01-02","kind":"short","q":"What are components of a computer system ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.2"],"model":[{"t":"Hardware: the CPU, memory and the input and output devices. It gives the basic computing power.","m":1},{"t":"Operating system: controls the hardware and shares it among the programs and users.","m":1},{"t":"Application programs (word processor, compiler, game) and the users who run them.","m":1}]},{"id":"cs-12-01-03","kind":"short","q":"What are services in operating systems ? List them.","marks":4,"src":["Guide ch.1 Operating Systems, Q.3"],"model":[{"t":"An OS gives services to programs and to users so that the work becomes easy.","m":1},{"t":"Program execution (load and run a program), input and output operations, file system handling.","m":1},{"t":"Communication between processes, error detection and handling.","m":1},{"t":"Resource allocation, protection and security, accounting of resource use.","m":1}]},{"id":"cs-12-01-04","kind":"short","q":"What is information management ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.4"],"model":[{"t":"Information management is the part of the OS that looks after the data kept on storage: files and directories.","m":1},{"t":"It stores, finds, shares, protects and deletes files, and it decides where on the disk a file is kept.","m":1},{"t":"It does this through the file system, device drivers and terminal input and output.","m":1}]},{"id":"cs-12-01-05","kind":"short","q":"What is system call ? List system calls in information management.","marks":4,"src":["Guide ch.1 Operating Systems, Q.5"],"model":[{"t":"A system call is a request made by a running program to the operating system to do a job for it, such as reading a file.","m":1},{"t":"It is the doorway between the user program and the OS kernel.","m":1},{"t":"File calls: create file, delete file, open, close.","m":1},{"t":"More file calls: read, write, reposition, get or set file attributes; also create directory.","m":1}]},{"id":"cs-12-01-06","kind":"short","q":"What is process management ? List system calls in process management.","marks":4,"src":["Guide ch.1 Operating Systems, Q.6"],"model":[{"t":"Process management is the OS work of creating, running, scheduling, stopping and synchronising processes.","m":1},{"t":"It decides which process gets the CPU and for how long.","m":1},{"t":"Calls: create process, terminate process, load and execute a program.","m":1},{"t":"More calls: wait for time or for an event, signal an event, get or set process attributes.","m":1}]},{"id":"cs-12-01-07","kind":"short","q":"What is memory management? List system calls in memory management.","marks":4,"src":["Guide ch.1 Operating Systems, Q.7"],"model":[{"t":"Memory management is the OS job of giving memory to processes and taking it back when they finish.","m":1},{"t":"It keeps track of which parts of memory are used and which are free, and protects one process from another.","m":1},{"t":"Calls: allocate (get) memory and free (release) memory.","m":1},{"t":"Other calls: get or set the size of memory used by a process.","m":1}]},{"id":"cs-12-01-08","kind":"short","q":"What are features of Windows 98 ?","marks":4,"src":["Guide ch.1 Operating Systems, Q.8"],"model":[{"t":"Single user, multitasking operating system with a graphical user interface (windows, icons, menus).","m":1},{"t":"Plug and play: new hardware is found and set up by the system.","m":1},{"t":"Long file names and the FAT32 file system for large disks; Internet and browser built into the desktop.","m":1},{"t":"Support for newer devices such as USB, and it can run both old 16-bit and new 32-bit programs.","m":1}]},{"id":"cs-12-01-09","kind":"short","q":"What are features of Windows - NT ?","marks":4,"src":["Guide ch.1 Operating Systems, Q.9"],"model":[{"t":"A 32-bit, multiuser, multitasking operating system (preemptive multitasking).","m":1},{"t":"Secure: users must log in, and files are protected through the NTFS file system and access rights.","m":1},{"t":"Portable and reliable: it runs on different hardware, and one failing program does not stop the system.","m":1},{"t":"Built-in networking, and it supports more than one CPU (multiprocessing).","m":1}]},{"id":"cs-12-01-10","kind":"short","q":"What are layers in Windows - NT ?","marks":4,"src":["Guide ch.1 Operating Systems, Q.10"],"model":[{"t":"Hardware Abstraction Layer (HAL): hides the differences of the hardware from the rest of the system.","m":1},{"t":"Kernel: schedules the work of the CPU and handles interrupts.","m":1},{"t":"Executive: the managers, such as the I/O manager, process manager, virtual memory manager and security monitor.","m":1},{"t":"Environment subsystems (such as Win32): let programs written for different systems run on top.","m":1}]},{"id":"cs-12-01-11","kind":"short","q":"What are features of Linux ?","marks":4,"src":["Guide ch.1 Operating Systems, Q.11"],"model":[{"t":"Open source: the program code is free to see, change and share. It is free of cost.","m":1},{"t":"Multiuser and multitasking, and it works on many kinds of hardware (portable).","m":1},{"t":"Secure, with user accounts, passwords and file permissions.","m":1},{"t":"Has a command shell, a hierarchical file system and a graphical desktop as well.","m":1}]},{"id":"cs-12-01-12","kind":"short","q":"What are components of Linux?","marks":3,"src":["Guide ch.1 Operating Systems, Q.12"],"model":[{"t":"Kernel: the core of Linux. It controls the memory, processes, files and devices.","m":1},{"t":"Shell: reads the commands typed by the user and passes them to the kernel.","m":1},{"t":"Utilities and application programs (editors, compilers, system tools) that the user runs.","m":1}]},{"id":"cs-12-01-13","kind":"short","q":"What is file system ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.13"],"model":[{"t":"The file system is the method an OS uses to name, store, organise and find files on a storage device.","m":1},{"t":"It keeps files in directories (folders) and controls how disk space is given to files.","m":1},{"t":"It also protects files by permissions. Examples: FAT32, NTFS, ext.","m":1}]},{"id":"cs-12-01-15","kind":"short","q":"What are advantages and disadvantages of tape based systems ?","marks":4,"src":["Guide ch.1 Operating Systems, Q.15"],"model":[{"t":"Advantage: tape is cheap and stores a large amount of data in little space.","m":1},{"t":"Advantage: it is light, easy to carry and good for keeping backups.","m":1},{"t":"Disadvantage: access is only sequential, so finding one record is slow because the tape must be wound to it.","m":1},{"t":"Disadvantage: not suitable for direct access or quick updates, and the tape wears with use.","m":1}]},{"id":"cs-12-01-16","kind":"short","q":"Define : Seek time and Latency time.","marks":3,"src":["Guide ch.1 Operating Systems, Q.16"],"model":[{"t":"Seek time: the time taken by the read-write head to move to the track that holds the data.","m":1},{"t":"Latency time (rotational delay): the time the disk takes to turn so that the needed sector comes under the head.","m":1},{"t":"The total disk access time is about seek time plus latency time plus the time to transfer the data.","m":1}]},{"id":"cs-12-01-17","kind":"short","q":"What is block ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.17"],"model":[{"t":"A block is a fixed-size group of disk sectors.","m":1},{"t":"It is the unit in which the operating system reads, writes and gives disk space to files.","m":1},{"t":"A file takes a whole number of blocks, so the last block may be partly empty.","m":1}]},{"id":"cs-12-01-18","kind":"short","q":"What is internal fragmentation ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.18"],"model":[{"t":"Internal fragmentation is memory wasted inside a space given to a process.","m":1},{"t":"It happens when the space (a fixed partition or a block) is larger than the process needs.","m":1},{"t":"The unused part inside it cannot be given to another process.","m":1}]},{"id":"cs-12-01-19","kind":"short","q":"What is external fragmentation ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.19"],"model":[{"t":"External fragmentation is free memory that lies in many small pieces between the used parts.","m":1},{"t":"The total free memory may be enough, but no single piece is big enough for a new process.","m":1},{"t":"It is cured by compaction, which joins the free pieces into one.","m":1}]},{"id":"cs-12-01-20","kind":"short","q":"What information is kept in directory entry ?","marks":4,"src":["Guide ch.1 Operating Systems, Q.20"],"model":[{"t":"File name and type of the file.","m":1},{"t":"Location of the file on the disk (address of the first block) and its size.","m":1},{"t":"Owner and protection (access rights) of the file.","m":1},{"t":"Dates and times of creation and last change.","m":1}]},{"id":"cs-12-01-21","kind":"short","q":"What are different file operations ?","marks":4,"src":["Guide ch.1 Operating Systems, Q.21"],"model":[{"t":"Create a file (find space and make a directory entry) and delete a file (free the space).","m":1},{"t":"Open a file before use and close it after use.","m":1},{"t":"Read data from a file and write data to a file.","m":1},{"t":"Reposition (seek) to a point in the file, and rename the file.","m":1}]},{"id":"cs-12-01-22","kind":"short","q":"What are sequential access and direct access ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.22"],"model":[{"t":"Sequential access: records are used one after another from the beginning, in order. Tape works this way.","m":1},{"t":"Direct (random) access: any record can be reached at once by its number or address, without reading the ones before it. Disk works this way.","m":1},{"t":"Direct access is faster for finding one record; sequential access is simple and good for processing all records.","m":1}]},{"id":"cs-12-01-23","kind":"short","q":"What are allocation methods ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.23"],"model":[{"t":"Contiguous allocation: a file gets one run of blocks next to each other.","m":1},{"t":"Linked allocation: the blocks of a file can lie anywhere; each block holds a pointer to the next.","m":1},{"t":"Indexed allocation: an index block keeps the list of all blocks of the file.","m":1}]},{"id":"cs-12-01-24","kind":"short","q":"What is compaction ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.24"],"model":[{"t":"Compaction means moving all the used parts of memory together to one end.","m":1},{"t":"The small free pieces then join into one large free block.","m":1},{"t":"It removes external fragmentation, but it takes CPU time to move the programs.","m":1}]},{"id":"cs-12-01-25","kind":"short","q":"What are device drivers ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.25"],"model":[{"t":"A device driver is a small program that controls one particular hardware device, such as a printer or a disk.","m":1},{"t":"It stands between the OS and the device and changes the OS commands into commands the device understands.","m":1},{"t":"Each new device needs its own driver.","m":1}]},{"id":"cs-12-01-26","kind":"short","q":"What is terminal ? What are its types ?","marks":4,"src":["Guide ch.1 Operating Systems, Q.26"],"model":[{"t":"A terminal is an input and output device (keyboard and screen) through which a user talks to the computer.","m":1},{"t":"Dumb terminal: only sends keystrokes and shows output; it has no processing power of its own.","m":1},{"t":"Smart terminal: can do a little processing, such as editing a line, by itself.","m":1},{"t":"Intelligent terminal: has its own processor and memory and can work without the main computer for a while.","m":1}]},{"id":"cs-12-01-27","kind":"short","q":"What is process ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.27"],"model":[{"t":"A process is a program that is being executed (a program in action).","m":1},{"t":"A program is only a file of instructions on the disk; it becomes a process when it is loaded and run.","m":1},{"t":"A process has its own code, data, stack, registers and a state.","m":1}]},{"id":"cs-12-01-28","kind":"short","q":"What is multiprogramming ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.28"],"model":[{"t":"Multiprogramming means keeping several programs in memory at the same time.","m":1},{"t":"When one program waits for input or output, the CPU is given to another program.","m":1},{"t":"So the CPU stays busy and is used better.","m":1}]},{"id":"cs-12-01-29","kind":"short","q":"What is context switching ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.29"],"model":[{"t":"Context switching is the change of the CPU from one process to another.","m":1},{"t":"The OS saves the state of the running process (registers and program counter) and loads the saved state of the next process.","m":1},{"t":"Later the first process continues exactly from where it stopped.","m":1}]},{"id":"cs-12-01-30","kind":"short","q":"What is degree of multiprogramming ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.30"],"model":[{"t":"It is the number of processes that are in memory at one time.","m":1},{"t":"A higher degree keeps the CPU busier, but each process gets less memory.","m":1},{"t":"It depends on the size of memory and on the size of the processes.","m":1}]},{"id":"cs-12-01-31","kind":"short","q":"What are process states ?","marks":4,"src":["Guide ch.1 Operating Systems, Q.31"],"model":[{"t":"New: the process is being created.","m":1},{"t":"Ready: it is in memory and waiting for the CPU. Running: it is using the CPU now.","m":1},{"t":"Waiting (blocked): it waits for an event such as an input or output to finish.","m":1},{"t":"Terminated: it has finished its work and is removed.","m":1}]},{"id":"cs-12-01-32","kind":"short","q":"What is process scheduling ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.32"],"model":[{"t":"Process scheduling is the OS job of choosing which ready process gets the CPU next and for how long.","m":1},{"t":"The part of the OS that does this is called the scheduler, and it follows a scheduling rule (algorithm).","m":1},{"t":"Good scheduling gives fair use of the CPU and a quick response.","m":1}]},{"id":"cs-12-01-33","kind":"short","q":"What is priority ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.33"],"model":[{"t":"Priority is a number given to a process to show how important it is.","m":1},{"t":"The OS gives the CPU first to the process with the higher priority.","m":1},{"t":"Priority can be fixed or can change while the process runs.","m":1}]},{"id":"cs-12-01-34","kind":"short","q":"What is multitasking ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.34"],"model":[{"t":"Multitasking means doing more than one task (process) at a time on one computer.","m":1},{"t":"The CPU switches between the tasks so fast that they seem to run together.","m":1},{"t":"Example: listening to music while typing a document.","m":1}]},{"id":"cs-12-01-35","kind":"short","q":"What is time sharing ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.35"],"model":[{"t":"Time sharing gives every user or process a short slice of CPU time in turn (a time quantum).","m":1},{"t":"The switching is so quick that each user feels the computer is only theirs.","m":1},{"t":"It is used by multiuser systems for interactive work.","m":1}]},{"id":"cs-12-01-36","kind":"short","q":"What are advantages of time sharing ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.36"],"model":[{"t":"Quick response to every user, so the system is interactive.","m":1},{"t":"Many users share one computer, so the cost per user is small, and the CPU idle time is low.","m":1},{"t":"Programs and data can be shared by the users.","m":1}]},{"id":"cs-12-01-37","kind":"short","q":"What functions are performed by memory management of operating system ?","marks":4,"src":["Guide ch.1 Operating Systems, Q.37"],"model":[{"t":"Keeps track of which parts of memory are in use and which are free.","m":1},{"t":"Decides which process gets memory, how much and when (allocation), and takes it back later (deallocation).","m":1},{"t":"Protects the memory of one process from another and from the OS.","m":1},{"t":"Moves processes in and out of memory when it is full (swapping), and manages virtual memory.","m":1}]},{"id":"cs-12-01-38","kind":"short","q":"Draw memory map of single user computer.","marks":3,"src":["Guide ch.1 Operating Systems, Q.38"],"model":[{"t":"Memory is one long strip of addresses, drawn as a box divided into parts.","m":1},{"t":"The operating system stays in one part (usually the lowest addresses).","m":1},{"t":"The user program takes the next part, and the rest is free (unused) memory.","m":1}],"code":"+----------------------+  high address\n|     Free memory      |\n+----------------------+\n|    User program      |\n+----------------------+\n|  Operating system    |\n+----------------------+  address 0"},{"id":"cs-12-01-39","kind":"short","q":"What is partitioning ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.39"],"model":[{"t":"Partitioning means dividing the main memory into parts, called partitions.","m":1},{"t":"Each partition holds one process, so several processes can be in memory (multiprogramming).","m":1},{"t":"The partitions can be fixed or variable in size.","m":1}]},{"id":"cs-12-01-40","kind":"short","q":"What are fixed partitions ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.40"],"model":[{"t":"In fixed partitioning memory is divided into parts of fixed size when the system starts, and the sizes do not change.","m":1},{"t":"A process is placed in a partition that is big enough for it.","m":1},{"t":"The unused part inside a partition is wasted (internal fragmentation).","m":1}]},{"id":"cs-12-01-41","kind":"short","q":"What are advantages of variable partitions over fixed partitions ?","marks":4,"src":["Guide ch.1 Operating Systems, Q.41"],"model":[{"t":"In variable partitions a process gets exactly the memory it needs, so there is no internal fragmentation.","m":1},{"t":"Memory is used better, because the partitions are made when processes arrive.","m":1},{"t":"Processes of different sizes can be handled easily.","m":1},{"t":"The number of processes in memory is not fixed in advance; it changes with their sizes.","m":1}]},{"id":"cs-12-01-42","kind":"short","q":"What is paging ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.42"],"model":[{"t":"In paging, memory is cut into equal blocks called frames and each program into pages of the same size.","m":1},{"t":"The pages can be put in any free frames, and a page table tells where each page is.","m":1},{"t":"It removes external fragmentation, and only the last page may waste some space.","m":1}]},{"id":"cs-12-01-43","kind":"short","q":"What is segmentation ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.43"],"model":[{"t":"Segmentation divides a program into logical parts called segments, such as code, data and stack.","m":1},{"t":"Segments can have different sizes, and a segment table gives the starting address and length of each.","m":1},{"t":"It matches the way a programmer thinks about the program.","m":1}]},{"id":"cs-12-01-44","kind":"short","q":"What is virtual memory ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.44"],"model":[{"t":"Virtual memory is a method that lets a program run even if it is larger than the main memory.","m":1},{"t":"Only the needed parts are kept in memory; the rest stay on the disk and are brought in when needed.","m":1},{"t":"It gives the user the feeling of a very large memory.","m":1}]},{"id":"cs-12-01-45","kind":"short","q":"What is page fault ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.45"],"model":[{"t":"A page fault happens when a program asks for a page that is not in main memory.","m":1},{"t":"The OS stops the process, finds the page on the disk and loads it into a free frame.","m":1},{"t":"Then the process starts again from the same instruction.","m":1}]},{"id":"cs-12-01-46","kind":"short","q":"What is dirty page ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.46"],"model":[{"t":"A dirty page is a page in memory that has been changed after it was loaded.","m":1},{"t":"The copy on the disk is old, so the page must be written back to the disk before it is replaced.","m":1},{"t":"A page that was not changed (clean) can simply be dropped.","m":1}]},{"id":"cs-12-01-47","kind":"short","q":"What is demand paging ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.47"],"model":[{"t":"In demand paging a page is loaded into memory only when the program needs it (on demand).","m":1},{"t":"A page fault tells the OS that a page is needed.","m":1},{"t":"Memory is saved and a program starts quickly, because the whole program is not loaded.","m":1}]},{"id":"cs-12-01-48","kind":"short","q":"What is GUI ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.48"],"model":[{"t":"GUI means Graphical User Interface.","m":1},{"t":"The user works with pictures: windows, icons, menus and a pointer, controlled by a mouse.","m":1},{"t":"It is easier than typing commands. Examples: Windows desktop, Linux desktops.","m":1}]},{"id":"cs-12-01-49","kind":"short","q":"What is a window ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.49"],"model":[{"t":"A window is a rectangular area of the screen that shows one program or one document.","m":1},{"t":"Many windows can be open at once, and each works on its own.","m":1},{"t":"It has a title bar, a border, scroll bars and buttons to minimise, maximise and close it.","m":1}]},{"id":"cs-12-01-50","kind":"short","q":"What are operations that can be performed on a window ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.50"],"model":[{"t":"Move the window and change its size (resize).","m":1},{"t":"Minimise (hide it to the task bar), maximise (fill the screen) and restore it.","m":1},{"t":"Close it, scroll its contents, and switch from one window to another.","m":1}]},{"id":"cs-12-01-51","kind":"short","q":"Define 'Security'.","marks":3,"src":["Guide ch.1 Operating Systems, Q.51"],"model":[{"t":"Security means protecting the computer system, its programs and its data.","m":1},{"t":"The protection is against unauthorised use, damage, theft and loss.","m":1},{"t":"The OS gives it by passwords, access rights and checks on every request.","m":1}]},{"id":"cs-12-01-52","kind":"short","q":"What are elements of security ?","marks":4,"src":["Guide ch.1 Operating Systems, Q.52"],"model":[{"t":"Confidentiality: only the allowed persons can read the information.","m":1},{"t":"Integrity: the information is not changed without permission.","m":1},{"t":"Availability: the system and data are ready for use whenever needed by the right users.","m":1},{"t":"Authentication: the system checks who the user really is.","m":1}]},{"id":"cs-12-01-53","kind":"short","q":"What are attacks on security ?","marks":4,"src":["Guide ch.1 Operating Systems, Q.53"],"model":[{"t":"Interruption: a resource is destroyed or made unavailable (attack on availability).","m":1},{"t":"Interception: an unauthorised person gets the data (attack on confidentiality).","m":1},{"t":"Modification: data is changed by an unauthorised person (attack on integrity).","m":1},{"t":"Fabrication: false data is put in the system as if genuine (attack on authenticity).","m":1}]},{"id":"cs-12-01-54","kind":"short","q":"What are types of security threats ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.54"],"model":[{"t":"Accidental threats: hardware failure, human error, fire or floods.","m":1},{"t":"Intentional threats: hackers, thieves and unauthorised users who try to steal or damage data.","m":1},{"t":"Programs that harm the system: viruses, worms, trojan horses and logic bombs.","m":1}]},{"id":"cs-12-01-55","kind":"short","q":"What are computer worms ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.55"],"model":[{"t":"A worm is a program that makes copies of itself and spreads from one computer to another over a network.","m":1},{"t":"It does not need a host file; it uses up the network and the memory and slows the computers.","m":1},{"t":"It can also carry other harmful code.","m":1}]},{"id":"cs-12-01-56","kind":"short","q":"What are computer viruses ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.56"],"model":[{"t":"A virus is a harmful program that attaches itself to another program or file.","m":1},{"t":"When the infected program is run, the virus runs and copies itself into other files.","m":1},{"t":"It can damage or delete data and slow the computer.","m":1}]},{"id":"cs-12-01-57","kind":"short","q":"Differentiate between computer worms and viruses.","marks":4,"src":["Guide ch.1 Operating Systems, Q.57"],"model":[{"t":"A virus needs a host file or program to attach to; a worm is a separate program that runs by itself.","m":1},{"t":"A virus spreads when a user runs the infected program or shares the file; a worm spreads by itself over a network.","m":1},{"t":"A virus mainly damages the files on one computer; a worm mainly uses up the network and the memory.","m":1},{"t":"Removing a virus means cleaning the infected files; a worm is removed as a whole program.","m":1}]},{"id":"cs-12-01-58","kind":"short","q":"What are infection methods of virus ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.58"],"model":[{"t":"Through infected removable disks, such as pen drives and CDs, that are shared among computers.","m":1},{"t":"Through e-mail attachments and files downloaded from the Internet.","m":1},{"t":"Through networks and shared files, and through pirated (illegal) software.","m":1}]},{"id":"cs-12-01-59","kind":"short","q":"How systems can be prevented from virus ?","marks":3,"src":["Guide ch.1 Operating Systems, Q.59"],"model":[{"t":"Use an antivirus program and keep it up to date; scan every disk, download and attachment.","m":1},{"t":"Use only original software from reliable sources, and do not open unknown e-mail attachments.","m":1},{"t":"Take regular backups so that data can be restored if a virus damages it.","m":1}]},{"id":"cs-12-01-ma","kind":"mcq","q":"Operating system is ................. .","marks":1,"src":["Guide ch.1 Operating Systems, Q.60(a)"],"options":["hardware.","program.","input device.","output device."],"ans":1,"why":"An operating system is system software, that is, a program. It controls the hardware but it is not hardware or a device."},{"id":"cs-12-01-mb","kind":"mcq","q":"................. is a service in operating system.","marks":1,"src":["Guide ch.1 Operating Systems, Q.60(b)"],"options":["Information management.","Process.","GUI.","None of these."],"ans":0,"why":"Information management (handling of files and data) is one of the services of an OS. A process is something the OS runs, and the GUI is an interface."},{"id":"cs-12-01-mc","kind":"mcq","q":"'Terminate a Process' is system call in .................","marks":1,"src":["Guide ch.1 Operating Systems, Q.60(c)"],"options":["IM.","PM.","MM.","None of these."],"ans":1,"why":"IM is information management, PM is process management and MM is memory management. Ending a process belongs to process management (PM)."},{"id":"cs-12-01-md","kind":"mcq","q":"Windows 98 is ................. operating system.","marks":1,"src":["Guide ch.1 Operating Systems, Q.60(d)"],"options":["Single user multitasking.","Multi user.","Time sharing.","None of these."],"ans":0,"why":"Windows 98 is for one user at a time, but it can run several programs together, so it is single user multitasking."},{"id":"cs-12-01-me","kind":"mcq","q":"Windows NT is ................. operating system.","marks":1,"src":["Guide ch.1 Operating Systems, Q.60(e)"],"options":["Single user multitasking.","Multiuser multitasking.","Time sharing.","None of these."],"ans":1,"why":"Windows NT lets several users work and runs many programs together, so it is multiuser multitasking."},{"id":"cs-12-01-mg","kind":"mcq","q":"The time required for read - write head to move to the correct track is .................","marks":1,"src":["Guide ch.1 Operating Systems, Q.60(g)"],"options":["Latency time.","Rotational delay.","Seek time.","None of these."],"ans":2,"why":"Seek time is the time for the head to move to the right track. Latency (rotational delay) is the extra time for the sector to turn under the head."},{"id":"cs-12-01-mh","kind":"mcq","q":"The free space list of block is .................","marks":1,"src":["Guide ch.1 Operating Systems, Q.60(h)"],"options":["memory map.","bit map.","block map.","none of these."],"ans":1,"why":"The free blocks of a disk are kept in a bit map: one bit per block, showing whether it is free or used."},{"id":"cs-12-01-p901","kind":"mcq","q":".......... is the only operating system from the following list.","marks":1,"src":["HSC March 2022 Paper I, Q.1A(a)"],"options":["MS point","Unix","MS Excel","Oracle"],"ans":1,"why":"Unix is an operating system. MS Paint is a drawing program, MS Excel is a spreadsheet and Oracle is a database."},{"id":"cs-12-01-p902","kind":"mcq","q":"Wastage of memory space within the partition is called as ..........","marks":1,"src":["HSC March 2023 Paper I, Q.1A(a)"],"options":["Internal fragmentation","External fragmentation","Compaction","Segmentation"],"ans":0,"why":"Space left unused inside a partition that is bigger than the program is internal fragmentation."},{"id":"cs-12-01-p903","kind":"mcq","q":"............... is a free operating system.","marks":1,"src":["HSC March 2024 Paper I, Q.1A(b)"],"options":["Unix","Windows","LINUX","DOS"],"ans":2,"why":"Linux is free (open source). Windows and DOS are commercial, and Unix is mostly commercial."},{"id":"cs-12-01-p904","kind":"short","q":"Explain the following terms with respect to virtual memory:\ni) Page fault\nii) Working set\niii) Demand paging\niv) Dirty bit.","marks":4,"src":["HSC March 2022 Paper I, Q.2B(b)"],"model":[{"t":"Page fault: the program uses a page that is not in main memory, so the hardware raises a fault and the operating system loads the page from the disk.","m":1},{"t":"Working set: the set of pages that a program is using actively in the present time. If it stays in memory the program runs with few page faults.","m":1},{"t":"Demand paging: a page is brought into memory only when it is needed (on a page fault), not all at the start.","m":1},{"t":"Dirty bit: a bit kept with each page. It is set when the page is changed in memory, so only a dirty page has to be written back to the disk when it is replaced.","m":1}]},{"id":"cs-12-01-p905","kind":"short","q":"What is Virtual Memory ? Explain following terms in virtual memory :\ni) page fault\nii) dirty page","marks":4,"src":["HSC March 2024 Paper I, Q.4B(b)"],"model":[{"t":"Virtual memory is a technique that lets a program larger than the main memory run: only the needed parts are kept in memory and the rest stays on the disk.","m":1},{"t":"It gives the user a large address space, and the operating system moves pages between disk and memory.","m":1},{"t":"Page fault: the program asks for a page that is not in memory. The hardware raises a fault, and the operating system brings the page in from the disk.","m":1},{"t":"Dirty page: a page in memory that was changed after it was loaded. It must be written back to the disk before its frame is reused; an unchanged page can just be dropped.","m":1}]},{"id":"cs-12-01-p906","kind":"short","q":"Explain the use of video RAM. Explain data byte and attribute byte.","marks":3,"src":["HSC March 2023 Paper I, Q.1B(c)"],"model":[{"t":"Video RAM is the memory of the display adapter. It holds what is shown on the screen, so the screen can be changed quickly without using the main memory.","m":1},{"t":"Data byte: in text mode each character on the screen takes two bytes in video RAM. The first (data) byte holds the ASCII code of the character.","m":1},{"t":"Attribute byte: the second byte holds how the character looks: foreground colour, background colour, blinking and intensity.","m":1}]},{"id":"cs-12-01-p907","kind":"short","q":"Explain function of each of following components of GUI :\ni) Title bar\nii) Scroll bars\niii) Minimize and Maximize or Restore button","marks":3,"src":["HSC March 2023 Paper I, Q.2A(a)"],"model":[{"t":"Title bar: the bar at the top of a window. It shows the name of the program or document, and the window can be dragged by it.","m":1},{"t":"Scroll bars: the vertical and horizontal bars at the side and the bottom. They move the hidden part of the contents into view.","m":1},{"t":"Minimize hides the window on the taskbar. Maximize makes it fill the whole screen, and Restore brings it back to its earlier size.","m":1}]},{"id":"cs-12-01-p908","kind":"short","q":"Explain the following components of GUI:\ni) Menu Bar\nii) Scroll Bar\niii) Title Bar","marks":3,"src":["HSC March 2024 Paper I, Q.1B(a)"],"model":[{"t":"Menu bar: the row below the title bar with menus such as File, Edit and View. Each menu opens a list of commands.","m":1},{"t":"Scroll bar: a bar at the right or the bottom of a window. Dragging it shows the part of the contents that does not fit.","m":1},{"t":"Title bar: the top bar that shows the name of the window and holds the control buttons; the window is moved by dragging it.","m":1}]},{"id":"cs-12-01-p909","kind":"short","q":"Explain page memory management system with a suitable Page Map Table (PMT).","marks":3,"src":["HSC March 2023 Paper I, Q.2A(c)"],"model":[{"t":"In paging the main memory is divided into equal blocks called frames, and the program is divided into pages of the same size. Any page can go into any free frame.","m":1},{"t":"The operating system keeps a page map table (PMT) for each process. It has one row per page and tells in which frame the page is loaded.","m":1},{"t":"Example: page 0 in frame 5, page 1 in frame 2, page 2 in frame 7. The logical address (page number, offset) is changed to the physical address (frame number, offset) using this table.","m":1}]},{"id":"cs-12-01-p910","kind":"short","q":"Define following :\ni) Track and Sector\nii) Seek time\niii) Transmission time\niv) Rotational delay","marks":4,"src":["HSC March 2023 Paper I, Q.2B(a)"],"model":[{"t":"Track: one circular path of data on a disk surface. Sector: a small fixed-size part of a track (usually 512 bytes), the smallest unit read or written.","m":1},{"t":"Seek time: the time the read-write head takes to move to the required track.","m":1},{"t":"Transmission time: the time taken to transfer the data between the disk and the memory once the head is in place.","m":1},{"t":"Rotational delay (latency): the time the disk takes to rotate so that the required sector comes under the head.","m":1}]},{"id":"cs-12-01-p911","kind":"short","q":"Which are three main areas in O.S. divides it's services ? Write example of each.","marks":3,"src":["HSC March 2023 Paper I, Q.3A(b)"],"model":[{"t":"Information management: handles files and devices. Example: opening, reading and writing a file.","m":1},{"t":"Process management: creates and controls processes. Example: running two programs, scheduling the processor.","m":1},{"t":"Memory management: allocates and frees main memory. Example: giving memory to a program when it starts and taking it back when it ends.","m":1}]},{"id":"cs-12-01-p912","kind":"short","q":"Defined following term of operating system:\ni) External Priority\nii) Internal Priority\niii) Purchase Priority\niv) Time Slice","marks":4,"src":["HSC March 2024 Paper I, Q.2B(a)"],"model":[{"t":"External priority: a priority given from outside the system, for example by the importance of the user or the job.","m":1},{"t":"Internal priority: a priority that the operating system sets itself from the process, for example from its memory need, time limit or number of files.","m":1},{"t":"Purchase priority: a user who pays more gets a higher priority for the job.","m":1},{"t":"Time slice: the fixed short time for which the processor is given to a process before it is moved to the next one (time sharing).","m":1}]},{"id":"cs-12-01-p913","kind":"short","q":"What is Partitioning? Explain fixed and variable partitioning of short.","marks":3,"src":["HSC March 2024 Paper I, Q.4A(b)"],"model":[{"t":"Partitioning divides the main memory into parts (partitions) so that several programs can be kept in memory at the same time.","m":1},{"t":"Fixed partitions: the number and the size of the partitions are decided at start and do not change. It is simple, but memory is wasted inside a partition (internal fragmentation).","m":1},{"t":"Variable partitions: a partition is made as big as the program needs when it arrives. It wastes less inside, but free holes appear between partitions (external fragmentation).","m":1}]}];
